-- Project Home V1. All user-visible tables remain protected by RLS.
create extension if not exists pgcrypto;
create schema if not exists app_private;

create type public.household_role as enum ('owner', 'adult', 'member', 'managed');
create type public.member_type as enum ('account', 'managed');
create type public.member_status as enum ('active', 'removed');
create type public.task_assignment as enum ('anyone', 'member', 'rotation');
create type public.task_status as enum ('open', 'completed', 'cancelled');
create type public.recurrence_anchor as enum ('scheduled', 'completion');
create type public.item_status as enum ('active', 'completed');
create type public.bill_status as enum ('active', 'paused', 'deleted');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text not null, display_name text not null check (btrim(display_name) <> ''), avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.households (id uuid primary key default gen_random_uuid(), name text not null check (btrim(name) <> ''), timezone text not null, currency char(3) not null check (currency ~ '^[A-Z]{3}$'), created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table public.household_members (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id), user_id uuid references public.profiles(id), display_name text not null check (btrim(display_name) <> ''), member_type public.member_type not null, role public.household_role not null default 'member', status public.member_status not null default 'active', created_by uuid not null references public.profiles(id), joined_at timestamptz not null default now(), removed_at timestamptz, check ((member_type = 'account' and user_id is not null) or (member_type = 'managed' and user_id is null)), check (member_type <> 'managed' or role <> 'owner'));
create unique index household_member_one_account on public.household_members(household_id, user_id) where user_id is not null and status = 'active';
create table public.household_invites (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id), token_hash text not null unique, created_by uuid not null references public.profiles(id), role public.household_role not null default 'member' check (role <> 'owner'), expires_at timestamptz not null, max_uses integer check (max_uses > 0), use_count integer not null default 0 check (use_count >= 0), revoked_at timestamptz, created_at timestamptz not null default now());
create table public.tasks (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id), title text not null check (btrim(title) <> ''), notes text, assignment_type public.task_assignment not null default 'anyone', assigned_member_id uuid references public.household_members(id), due_at timestamptz, snoozed_until timestamptz, recurrence_type text not null default 'none' check (recurrence_type in ('none','daily','weekly','monthly','interval')), recurrence_anchor public.recurrence_anchor not null default 'scheduled', recurrence_config jsonb, rotation_index integer not null default 0 check (rotation_index >= 0), status public.task_status not null default 'open', created_by uuid not null references public.profiles(id), completed_at timestamptz, completed_by_member_id uuid references public.household_members(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1 check (version > 0));
create table public.task_rotation_members (task_id uuid not null references public.tasks(id) on delete cascade, member_id uuid not null references public.household_members(id), position integer not null check (position >= 0), primary key(task_id, member_id), unique(task_id, position));
create table public.task_completions (id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id), household_id uuid not null references public.households(id), completed_by_member_id uuid not null references public.household_members(id), completed_at timestamptz not null default now(), scheduled_due_at timestamptz, client_mutation_id uuid not null unique, created_at timestamptz not null default now());
create table public.shopping_lists (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id), name text not null check (btrim(name) <> ''), is_default boolean not null default false, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create unique index one_default_shopping_list on public.shopping_lists(household_id) where is_default;
create table public.shopping_items (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id), list_id uuid not null references public.shopping_lists(id), name text not null check (btrim(name) <> ''), quantity text, category text, note text, status public.item_status not null default 'active', created_by_member_id uuid not null references public.household_members(id), completed_by_member_id uuid references public.household_members(id), completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1 check (version > 0));
create table public.events (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id), title text not null check (btrim(title) <> ''), description text, starts_at timestamptz not null, ends_at timestamptz, all_day boolean not null default false, recurrence_config jsonb, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1 check(version > 0), check (ends_at is null or ends_at >= starts_at));
create table public.event_members (event_id uuid not null references public.events(id) on delete cascade, member_id uuid not null references public.household_members(id), primary key(event_id, member_id));
create table public.expenses (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id), title text not null check (btrim(title) <> ''), amount_minor bigint not null check(amount_minor > 0), currency char(3) not null check(currency ~ '^[A-Z]{3}$'), paid_by_member_id uuid not null references public.household_members(id), expense_date date not null default current_date, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1 check(version > 0));
create table public.expense_splits (id uuid primary key default gen_random_uuid(), expense_id uuid not null references public.expenses(id) on delete cascade, household_id uuid not null references public.households(id), member_id uuid not null references public.household_members(id), amount_minor bigint not null check(amount_minor >= 0), created_at timestamptz not null default now(), unique(expense_id, member_id));
create table public.settlements (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id), from_member_id uuid not null references public.household_members(id), to_member_id uuid not null references public.household_members(id), amount_minor bigint not null check(amount_minor > 0), currency char(3) not null check(currency ~ '^[A-Z]{3}$'), settled_at timestamptz not null default now(), created_by uuid not null references public.profiles(id), client_mutation_id uuid not null unique, created_at timestamptz not null default now(), check(from_member_id <> to_member_id));
create table public.bills (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id), name text not null check(btrim(name) <> ''), amount_minor bigint not null check(amount_minor > 0), currency char(3) not null check(currency ~ '^[A-Z]{3}$'), due_at timestamptz not null, assigned_member_id uuid references public.household_members(id), recurrence_type text not null default 'none' check(recurrence_type in ('none','daily','weekly','monthly','yearly','interval')), recurrence_config jsonb, reminder_config jsonb not null default '{}'::jsonb, status public.bill_status not null default 'active', created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1 check(version > 0));
create table public.bill_payments (id uuid primary key default gen_random_uuid(), bill_id uuid not null references public.bills(id), household_id uuid not null references public.households(id), amount_minor bigint not null check(amount_minor > 0), due_at timestamptz not null, paid_at timestamptz not null default now(), paid_by_member_id uuid not null references public.household_members(id), client_mutation_id uuid not null unique, created_at timestamptz not null default now());
create table public.activity_events (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id), actor_member_id uuid references public.household_members(id), type text not null check(btrim(type) <> ''), entity_type text not null check(btrim(entity_type) <> ''), entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.device_tokens (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, platform text not null check(platform in ('ios','android','web')), push_token text not null, device_id text not null, enabled boolean not null default true, last_seen_at timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, device_id));
create table public.notification_preferences (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, household_id uuid not null references public.households(id), tasks boolean not null default true, events boolean not null default true, shopping boolean not null default false, bills boolean not null default true, activity boolean not null default false, quiet_hours_start time, quiet_hours_end time, unique(user_id, household_id));

create index household_members_household_user on public.household_members(household_id, user_id); create index tasks_household_due on public.tasks(household_id, due_at); create index tasks_household_status on public.tasks(household_id, status); create index shopping_items_list_status on public.shopping_items(list_id, status); create index events_household_starts on public.events(household_id, starts_at); create index expenses_household_date on public.expenses(household_id, expense_date); create index bills_household_due on public.bills(household_id, due_at); create index activity_household_created on public.activity_events(household_id, created_at desc); create index device_tokens_user on public.device_tokens(user_id);

create or replace function app_private.touch_row() returns trigger language plpgsql set search_path = public as $$ begin new.updated_at = now(); new.version = old.version + 1; return new; end $$;
create trigger touch_task before update on public.tasks for each row execute procedure app_private.touch_row(); create trigger touch_item before update on public.shopping_items for each row execute procedure app_private.touch_row(); create trigger touch_event before update on public.events for each row execute procedure app_private.touch_row(); create trigger touch_expense before update on public.expenses for each row execute procedure app_private.touch_row(); create trigger touch_bill before update on public.bills for each row execute procedure app_private.touch_row();
create or replace function app_private.is_member(target_household uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from household_members m join households h on h.id=m.household_id where m.household_id=target_household and m.user_id=auth.uid() and m.status='active' and h.deleted_at is null) $$;
create or replace function app_private.is_adult(target_household uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from household_members where household_id=target_household and user_id=auth.uid() and status='active' and role in ('owner','adult')) $$;
grant usage on schema public to authenticated; grant select, insert, update, delete on all tables in schema public to authenticated; grant usage on schema app_private to authenticated; grant execute on all functions in schema app_private to authenticated;

alter table public.profiles enable row level security; alter table public.households enable row level security; alter table public.household_members enable row level security; alter table public.household_invites enable row level security; alter table public.tasks enable row level security; alter table public.task_rotation_members enable row level security; alter table public.task_completions enable row level security; alter table public.shopping_lists enable row level security; alter table public.shopping_items enable row level security; alter table public.events enable row level security; alter table public.event_members enable row level security; alter table public.expenses enable row level security; alter table public.expense_splits enable row level security; alter table public.settlements enable row level security; alter table public.bills enable row level security; alter table public.bill_payments enable row level security; alter table public.activity_events enable row level security; alter table public.device_tokens enable row level security; alter table public.notification_preferences enable row level security;
create policy profile_self on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy household_read on public.households for select to authenticated using(app_private.is_member(id));
create policy member_read on public.household_members for select to authenticated using(app_private.is_member(household_id));
create policy invite_admin on public.household_invites for all to authenticated using(app_private.is_adult(household_id)) with check(app_private.is_adult(household_id));
create policy task_member on public.tasks for all to authenticated using(app_private.is_member(household_id)) with check(app_private.is_member(household_id));
create policy rotation_member on public.task_rotation_members for all to authenticated using(exists(select 1 from public.tasks t where t.id=task_id and app_private.is_member(t.household_id))) with check(exists(select 1 from public.tasks t where t.id=task_id and app_private.is_member(t.household_id)));
create policy completion_read on public.task_completions for select to authenticated using(app_private.is_member(household_id));
create policy list_member on public.shopping_lists for all to authenticated using(app_private.is_member(household_id)) with check(app_private.is_member(household_id));
create policy item_member on public.shopping_items for all to authenticated using(app_private.is_member(household_id)) with check(app_private.is_member(household_id));
create policy event_member on public.events for all to authenticated using(app_private.is_member(household_id)) with check(app_private.is_member(household_id));
create policy event_member_link on public.event_members for all to authenticated using(exists(select 1 from public.events e where e.id=event_id and app_private.is_member(e.household_id))) with check(exists(select 1 from public.events e where e.id=event_id and app_private.is_member(e.household_id)));
create policy expense_read on public.expenses for select to authenticated using(app_private.is_member(household_id)); create policy split_read on public.expense_splits for select to authenticated using(app_private.is_member(household_id)); create policy settlement_read on public.settlements for select to authenticated using(app_private.is_member(household_id)); create policy bill_read on public.bills for select to authenticated using(app_private.is_member(household_id)); create policy payment_read on public.bill_payments for select to authenticated using(app_private.is_member(household_id)); create policy activity_read on public.activity_events for select to authenticated using(app_private.is_member(household_id));
create policy tokens_self on public.device_tokens for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy preferences_self on public.notification_preferences for all to authenticated using(user_id=auth.uid() and app_private.is_member(household_id)) with check(user_id=auth.uid() and app_private.is_member(household_id));

create or replace function public.complete_task(p_task_id uuid, p_member_id uuid, p_client_mutation_id uuid, p_completed_at timestamptz default now()) returns public.tasks language plpgsql security definer set search_path = public, app_private as $$ declare task_row public.tasks; begin select * into task_row from tasks where id=p_task_id for update; if not found or not app_private.is_member(task_row.household_id) then raise exception 'Task not found or access denied'; end if; if exists(select 1 from task_completions where client_mutation_id=p_client_mutation_id) then return task_row; end if; if task_row.status <> 'open' then raise exception 'Task is already completed'; end if; if not exists(select 1 from household_members where id=p_member_id and household_id=task_row.household_id and status='active') then raise exception 'Invalid completing member'; end if; insert into task_completions(task_id, household_id, completed_by_member_id, completed_at, scheduled_due_at, client_mutation_id) values(task_row.id, task_row.household_id, p_member_id, p_completed_at, task_row.due_at, p_client_mutation_id); update tasks set status='completed', completed_at=p_completed_at, completed_by_member_id=p_member_id where id=task_row.id returning * into task_row; insert into activity_events(household_id, actor_member_id, type, entity_type, entity_id) values(task_row.household_id,p_member_id,'task.completed','task',task_row.id); return task_row; end $$;
revoke all on function public.complete_task(uuid,uuid,uuid,timestamptz) from public; grant execute on function public.complete_task(uuid,uuid,uuid,timestamptz) to authenticated;

create or replace function public.create_household(p_name text, p_timezone text, p_currency char(3)) returns uuid language plpgsql security definer set search_path = public as $$ declare new_household uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not exists(select 1 from profiles where id=auth.uid()) then raise exception 'Profile required'; end if; insert into households(name, timezone, currency, created_by) values(btrim(p_name),p_timezone,p_currency,auth.uid()) returning id into new_household; insert into household_members(household_id,user_id,display_name,member_type,role,created_by) select new_household,id,display_name,'account','owner',id from profiles where id=auth.uid(); insert into shopping_lists(household_id,name,is_default,created_by) values(new_household,'Shopping',true,auth.uid()); insert into activity_events(household_id,type,entity_type,entity_id) values(new_household,'household.created','household',new_household); return new_household; end $$;
create or replace function public.accept_household_invite(p_token text) returns uuid language plpgsql security definer set search_path = public, app_private as $$ declare invite_row household_invites; member_id uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select * into invite_row from household_invites where token_hash=encode(digest(p_token,'sha256'),'hex') for update; if not found or invite_row.expires_at <= now() or invite_row.revoked_at is not null or (invite_row.max_uses is not null and invite_row.use_count >= invite_row.max_uses) then raise exception 'This invite is no longer valid'; end if; if exists(select 1 from household_members where household_id=invite_row.household_id and user_id=auth.uid() and status='active') then raise exception 'Already a member'; end if; insert into household_members(household_id,user_id,display_name,member_type,role,created_by) select invite_row.household_id,id,display_name,'account',invite_row.role,invite_row.created_by from profiles where id=auth.uid() returning id into member_id; update household_invites set use_count=use_count+1 where id=invite_row.id; insert into activity_events(household_id,actor_member_id,type,entity_type,entity_id) values(invite_row.household_id,member_id,'member.joined','member',member_id); return invite_row.household_id; end $$;
create or replace function public.mark_bill_paid(p_bill_id uuid, p_member_id uuid, p_client_mutation_id uuid, p_paid_at timestamptz default now()) returns public.bills language plpgsql security definer set search_path = public, app_private as $$ declare bill_row public.bills; begin select * into bill_row from bills where id=p_bill_id for update; if not found or not app_private.is_member(bill_row.household_id) then raise exception 'Bill not found or access denied'; end if; if exists(select 1 from bill_payments where client_mutation_id=p_client_mutation_id) then return bill_row; end if; if bill_row.status <> 'active' then raise exception 'Bill is not active'; end if; if not exists(select 1 from household_members where id=p_member_id and household_id=bill_row.household_id and status='active') then raise exception 'Invalid paying member'; end if; insert into bill_payments(bill_id,household_id,amount_minor,due_at,paid_at,paid_by_member_id,client_mutation_id) values(bill_row.id,bill_row.household_id,bill_row.amount_minor,bill_row.due_at,p_paid_at,p_member_id,p_client_mutation_id); if bill_row.recurrence_type='daily' then update bills set due_at=bill_row.due_at + interval '1 day' where id=bill_row.id returning * into bill_row; elsif bill_row.recurrence_type='weekly' then update bills set due_at=bill_row.due_at + interval '1 week' where id=bill_row.id returning * into bill_row; elsif bill_row.recurrence_type='monthly' then update bills set due_at=bill_row.due_at + interval '1 month' where id=bill_row.id returning * into bill_row; elsif bill_row.recurrence_type='yearly' then update bills set due_at=bill_row.due_at + interval '1 year' where id=bill_row.id returning * into bill_row; else update bills set status='paused' where id=bill_row.id returning * into bill_row; end if; insert into activity_events(household_id,actor_member_id,type,entity_type,entity_id) values(bill_row.household_id,p_member_id,'bill.paid','bill',bill_row.id); return bill_row; end $$;
revoke all on function public.create_household(text,text,char) from public; revoke all on function public.accept_household_invite(text) from public; revoke all on function public.mark_bill_paid(uuid,uuid,uuid,timestamptz) from public; grant execute on function public.create_household(text,text,char) to authenticated; grant execute on function public.accept_household_invite(text) to authenticated; grant execute on function public.mark_bill_paid(uuid,uuid,uuid,timestamptz) to authenticated;
